<?php
declare(strict_types=1);
define('WP_CLI',true);require __DIR__.'/bootstrap.php';
use AISkillsHub\Core\Accounts\Crypto;
$service=$core->get('learning_subscriptions');$worker=$core->get('account_mail_worker');$saved=$service->snapshot();wp_set_current_user($admin);$service->saveConfig(['enabled'=>true,'paused'=>false],$saved['revision']);$f=get_option('aish_p14_newsletter_race');$prefix=substr(get_userdata($f['a'])->user_login,0,-strlen('campaign-race-a'));$messages=[];add_filter('pre_wp_mail',static function($value,$message)use(&$messages){$messages[]=$message;return true;},PHP_INT_MAX,2);
$send=function(int$id)use($db,$worker):void{$table=$db->table('notification_outbox');$db->execute("UPDATE $table SET available_at='1971-01-01 00:00:00' WHERE id=%d",[$id]);$filter=static function(string$sql)use($table,$id):string{if(str_starts_with($sql,"SELECT * FROM $table WHERE status IN ('queued','retry')")&&str_ends_with($sql,' LIMIT 1 FOR UPDATE'))return str_replace(' ORDER BY ',' AND id='.$id.' ORDER BY ',$sql);return$sql;};add_filter('query',$filter,PHP_INT_MAX);try{$worker->run();}finally{remove_filter('query',$filter,PHP_INT_MAX);}};
$read=fn(int$id):?array=>$db->row('SELECT * FROM '.$db->table('notification_outbox').' WHERE id=%d',[$id]);
try{foreach(['en_US'=>'owner','zh_CN'=>'chinese']as$locale=>$suffix){
p14_case('new_resource_digest_current_language_pause_resume_and_http_headers_'.$locale,function()use($service,$locale,$suffix,$prefix,$db,$send,$read,&$messages){$service->saveConfig(['enabled'=>true,'paused'=>false],$service->snapshot()['revision']);$user=(int)$db->value('SELECT ID FROM '.$db->connection()->users.' WHERE user_login=%s',[$prefix.'campaign-'.$suffix]);$preview=$service->preview($locale,'new_resources');$issue=$service->queueIssue($locale,'new_resources',bin2hex(random_bytes(32)),$preview['fingerprint']);for($i=0;$i<30;$i++){$service->tick();if($service->issueDetail($issue)['state']==='complete')break;}p14_assert($service->issueDetail($issue)['state']==='complete','Bounded new-resource campaign finishes');$row=$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_new' ORDER BY id DESC LIMIT 1",[$user]);p14_assert($row!==null&&$row['locale']===$locale,'Only confirmed matching preference/locale has owned message');$service->saveConfig(['enabled'=>true,'paused'=>true],$service->snapshot()['revision']);$before=count($messages);$send((int)$row['id']);$deferred=$read((int)$row['id']);p14_assert($deferred['status']==='queued'&&(int)$deferred['attempts']===0&&$deferred['payload_ciphertext']!==null&&count($messages)===$before,'Paused digest retains encrypted payload without consuming a transport attempt');$service->saveConfig(['enabled'=>true,'paused'=>false],$service->snapshot()['revision']);$send((int)$row['id']);p14_assert($read((int)$row['id'])['status']==='accepted'&&count($messages)===$before+1,'Resume produces one intercepted transport acceptance');$message=end($messages);$headers=is_array($message['headers'])?implode("\n",$message['headers']):$message['headers'];p14_assert(str_contains($headers,'List-Unsubscribe: <http://127.0.0.1:')&&!str_contains($headers,'List-Unsubscribe-Post:'),'HTTP QA carries cancel URL but correctly omits HTTPS-only RFC8058 one-click advertisement');$s=$service->rawState($user);$token=Crypto::newsletterToken($user,$s['generation'],$s['nonce'],$s['key_version'])['token'];p14_assert(str_contains($message['message'],$token),'Weekly/new-resource message uses stable same-generation cancellation token');p14_assert(str_contains($message['message'],$locale==='zh_CN'?'/zh/':'/en/')&&str_contains($message['subject'],$locale==='zh_CN'?'新资源通知':'New resources'),'Actual bilingual new-resource template and URLs match recipient preference');});
}}finally{wp_set_current_user($admin);$service->saveConfig(array_intersect_key($saved,['enabled'=>true,'paused'=>true]),$service->snapshot()['revision']);}
p14_report('Real WordPress/MySQL opt-in new-resource campaigns, pause/resume, bilingual URLs and HTTP-safe unsubscribe headers; actual message transport intercepted by pre_wp_mail, real HTTPS/SMTP delivery not verified');
